@font-face{font-family:'SUIT Variable';font-weight:100 900;font-display:swap;src:url(data:font/woff2;base64,) format('woff2-variations');}@font-face{font-family:'Inter Tight';font-weight:400;font-display:block;src:url(data:font/ttf;base64,) format('truetype')}
